static LoiArenaChunk* loi_arena_chunk_at(size_t offset) {
    for (LoiArenaChunk* chunk = loi_arena_chunks; chunk != NULL; chunk = chunk->next) {
        if (offset >= chunk->base && offset < chunk->base + chunk->size) {
            return chunk;
        }
    }
    return NULL;
}

static LoiArenaChunk* loi_arena_chunk_from(size_t offset, size_t size) {
    for (LoiArenaChunk* chunk = loi_arena_chunks; chunk != NULL; chunk = chunk->next) {
        if (chunk->base >= offset && chunk->size >= size) {
            return chunk;
        }
    }
    return NULL;
}

static void loi_arena_grow(size_t minimum, size_t line, size_t column) {
    size_t chunk_size = loi_arena_next_size;
    if (chunk_size < minimum) {
        chunk_size = minimum;
    }
    if (chunk_size > SIZE_MAX - 7u) {
        loi_runtime_fail("allocation size overflow", line, column);
    }
    chunk_size = (chunk_size + 7u) & ~(size_t)7u;
    if (chunk_size > SIZE_MAX - loi_arena_capacity) {
        loi_runtime_fail("arena capacity overflow", line, column);
    }

    LoiArenaChunk* chunk = (LoiArenaChunk*)malloc(sizeof(*chunk));
    if (chunk == NULL) {
        loi_runtime_fail("arena allocation failed", line, column);
    }
    unsigned char* data = (unsigned char*)malloc(chunk_size);
    if (data == NULL) {
        free(chunk);
        loi_runtime_fail("arena allocation failed", line, column);
    }
    chunk->next = NULL;
    chunk->base = loi_arena_capacity;
    chunk->size = chunk_size;
    chunk->data = data;
    if (loi_arena_chunks == NULL) {
        loi_arena_chunks = chunk;
    } else {
        LoiArenaChunk* tail = loi_arena_chunks;
        while (tail->next != NULL) {
            tail = tail->next;
        }
        tail->next = chunk;
    }
    loi_arena_capacity += chunk_size;
    loi_arena_current = chunk;
    loi_arena_top = chunk->base;
    if (chunk_size <= SIZE_MAX / 2) {
        loi_arena_next_size = chunk_size * 2;
    } else {
        loi_arena_next_size = chunk_size;
    }
}

static inline void* loi_alloc(size_t size, size_t line, size_t column) {
    if (size > SIZE_MAX - 7u) {
        loi_runtime_fail("allocation size overflow", line, column);
    }
    if (size == 0) {
        size = 8;
    }
    size = (size + 7u) & ~(size_t)7u;

    /* `loi_arena_top` may have been restored directly (protect blocks and
     * user C code do that), so resynchronise the current chunk lazily. */
    LoiArenaChunk* chunk = loi_arena_current;
    if (chunk == NULL
        || loi_arena_top < chunk->base
        || loi_arena_top > chunk->base + chunk->size) {
        chunk = loi_arena_chunk_at(loi_arena_top);
        loi_arena_current = chunk;
    }

    size_t available = 0;
    if (chunk != NULL && loi_arena_top >= chunk->base) {
        available = chunk->base + chunk->size - loi_arena_top;
    }
    if (chunk == NULL || available < size) {
        LoiArenaChunk* reuse = loi_arena_chunk_from(loi_arena_top, size);
        if (reuse != NULL) {
            chunk = reuse;
            loi_arena_current = chunk;
            loi_arena_top = chunk->base;
        } else {
            loi_arena_grow(size, line, column);
            chunk = loi_arena_current;
        }
    }

    void* result = chunk->data + (loi_arena_top - chunk->base);
    loi_arena_top += size;
    return result;
}

static inline LoiSlice loi_alloc_slice(size_t count, size_t element_size, size_t line, size_t column) {
    if (element_size != 0 && count > SIZE_MAX / element_size) {
        loi_runtime_fail("slice allocation overflow", line, column);
    }
    LoiSlice slice;
    slice.data = loi_alloc(count * element_size, line, column);
    slice.len = count;
    return slice;
}

static inline bool loi_slice_eq(LoiSlice left, LoiSlice right) {
    return left.len == right.len
        && (left.len == 0 || memcmp(left.data, right.data, left.len) == 0);
}

/* File, standard-input and numeric-printing helpers. Paths are byte slices,
 * not C strings, so they are copied into a temporary NUL-terminated buffer.
 * Returned file/stdin data lives in the current arena and must be used inside
 * a `protect` block. */

static inline char* loi_temp_path(LoiSlice path, size_t line, size_t column) {
    if (path.len == SIZE_MAX) {
        loi_runtime_fail("file path is too long", line, column);
    }
    char* name = (char*)malloc(path.len + 1);
    if (name == NULL) {
        loi_runtime_fail("out of memory reading file path", line, column);
    }
    if (path.len != 0) {
        memcpy(name, path.data, path.len);
    }
    name[path.len] = '\0';
    return name;
}

static inline LoiSlice loi_read_file(LoiSlice path, size_t line, size_t column) {
    char* name = loi_temp_path(path, line, column);
    FILE* file = fopen(name, "rb");
    free(name);
    if (file == NULL) {
        loi_runtime_fail("could not open file", line, column);
    }
    if (fseek(file, 0, SEEK_END) != 0) {
        fclose(file);
        loi_runtime_fail("could not read file", line, column);
    }
    long end = ftell(file);
    if (end < 0 || fseek(file, 0, SEEK_SET) != 0) {
        fclose(file);
        loi_runtime_fail("could not read file", line, column);
    }
    LoiSlice out;
    out.len = (size_t)end;
    out.data = loi_alloc(out.len, line, column);
    if (out.len != 0 && fread(out.data, 1, out.len, file) != out.len) {
        fclose(file);
        loi_runtime_fail("could not read file", line, column);
    }
    if (fclose(file) != 0) {
        loi_runtime_fail("could not read file", line, column);
    }
    return out;
}

static inline bool loi_write_file(LoiSlice path, LoiSlice data, size_t line, size_t column) {
    char* name = loi_temp_path(path, line, column);
    FILE* file = fopen(name, "wb");
    free(name);
    if (file == NULL) {
        return false;
    }
    bool ok = data.len == 0 || fwrite(data.data, 1, data.len, file) == data.len;
    if (fclose(file) != 0) {
        ok = false;
    }
    return ok;
}

static inline LoiSlice loi_read_stdin(size_t line, size_t column) {
    size_t capacity = 4096;
    size_t length = 0;
    unsigned char* buffer = (unsigned char*)malloc(capacity);
    if (buffer == NULL) {
        loi_runtime_fail("out of memory reading stdin", line, column);
    }
    for (;;) {
        if (length == capacity) {
            if (capacity > SIZE_MAX / 2) {
                free(buffer);
                loi_runtime_fail("stdin input is too large", line, column);
            }
            capacity *= 2;
            unsigned char* grown = (unsigned char*)realloc(buffer, capacity);
            if (grown == NULL) {
                free(buffer);
                loi_runtime_fail("out of memory reading stdin", line, column);
            }
            buffer = grown;
        }
        size_t count = fread(buffer + length, 1, capacity - length, stdin);
        length += count;
        if (count == 0) {
            break;
        }
    }
    if (ferror(stdin)) {
        free(buffer);
        loi_runtime_fail("could not read stdin", line, column);
    }
    LoiSlice out;
    out.len = length;
    out.data = loi_alloc(length, line, column);
    if (length != 0) {
        memcpy(out.data, buffer, length);
    }
    free(buffer);
    return out;
}

static inline LoiSlice loi_read_line(size_t line, size_t column) {
    size_t capacity = 128;
    size_t length = 0;
    unsigned char* buffer = (unsigned char*)malloc(capacity);
    if (buffer == NULL) {
        loi_runtime_fail("out of memory reading stdin", line, column);
    }
    int ch;
    while ((ch = getchar()) != EOF && ch != '\n') {
        if (length == capacity) {
            if (capacity > SIZE_MAX / 2) {
                free(buffer);
                loi_runtime_fail("stdin input is too large", line, column);
            }
            capacity *= 2;
            unsigned char* grown = (unsigned char*)realloc(buffer, capacity);
            if (grown == NULL) {
                free(buffer);
                loi_runtime_fail("out of memory reading stdin", line, column);
            }
            buffer = grown;
        }
        buffer[length++] = (unsigned char)ch;
    }
    if (ch == EOF && ferror(stdin)) {
        free(buffer);
        loi_runtime_fail("could not read stdin", line, column);
    }
    if (length != 0 && buffer[length - 1] == '\r') {
        length--;
    }
    LoiSlice out;
    out.len = length;
    out.data = loi_alloc(length, line, column);
    if (length != 0) {
        memcpy(out.data, buffer, length);
    }
    free(buffer);
    return out;
}

static inline void loi_print_int(int64_t value) {
    printf("%lld", (long long)value);
}

static inline void loi_print_uint(uint64_t value) {
    printf("%llu", (unsigned long long)value);
}

static inline void loi_print_float(double value) {
    char buffer[32];
    int precision;
    for (precision = 1; precision <= 17; precision++) {
        snprintf(buffer, sizeof buffer, "%.*g", precision, value);
        if (strtod(buffer, NULL) == value) {
            break;
        }
    }
    fputs(buffer, stdout);
}

static inline LoiSlice loi_format(size_t line, size_t column, const char* fmt, ...) {
    va_list args;
    va_list args_copy;
    va_start(args, fmt);
    va_copy(args_copy, args);
    int needed = vsnprintf(NULL, 0, fmt, args);
    va_end(args);
    if (needed < 0) {
        va_end(args_copy);
        loi_runtime_fail("format failed", line, column);
    }
    size_t size = (size_t)needed;
    LoiSlice out;
    out.len = size;
    out.data = loi_alloc(size + 1, line, column);
    vsnprintf((char*)out.data, size + 1, fmt, args_copy);
    va_end(args_copy);
    return out;
}

static inline void* loi_index(LoiSlice slice, size_t index, size_t element_size, size_t line, size_t column) {
    if (index >= slice.len) {
        loi_runtime_fail("slice index out of bounds", line, column);
    }
    return (unsigned char*)slice.data + index * element_size;
}

static inline LoiSlice loi_view(LoiSlice source, uint64_t start, uint64_t end, size_t element_size, size_t line, size_t column) {
    if (start > end || end > source.len) {
        loi_runtime_fail("view range out of bounds", line, column);
    }
    LoiSlice out;
    out.data = (unsigned char*)source.data + (size_t)start * element_size;
    out.len = (size_t)(end - start);
    return out;
}

